function setTab(tab){activeTab=tab;document.body.classList.toggle('learning-mode',tab!=='game'||!!tutorial);for(const name of ['game','learn','pieces']){$('#panel-'+name).hidden=name!==tab;$('#tab-'+name).classList.toggle('active',name===tab);$('#tab-'+name).setAttribute('aria-selected',name===tab);}$('#nav-learn').classList.toggle('active',tab==='learn');$('#nav-play').classList.toggle('active',tab!=='learn');}
function startLesson(index){stopBot();auto=false;if(!tutorial)liveMatch={state:s,past,journal,flipped};tutorial={index,step:0,done:false,hint:false};s=LESSONS[index].state();past=[];journal=[];mode=LESSONS[index].steps[0].mode;deployType=LESSONS[index].steps[0].piece||'p';selected=null;flipped=false;revision++;notice='';setTab('learn');render();}
function exitLesson(){if(!tutorial){setTab('game');return;}stopBot();s=liveMatch.state;past=liveMatch.past;journal=liveMatch.journal;flipped=liveMatch.flipped;liveMatch=null;tutorial=null;selected=null;mode='move';revision++;notice='';setTab('game');render();}
function renderLesson(){$('#learn-progress').textContent=completed.size+' / '+LESSONS.length;$('#lesson-active').hidden=!tutorial;$('#lesson-list').replaceChildren();for(const [i,l] of LESSONS.entries()){const b=document.createElement('button');b.className='lesson-button'+(completed.has(i)?' done':'')+(tutorial?.index===i?' current':'');b.innerHTML=`<span class="lesson-num">${completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${l.title}<small>${l.category}</small></span>`;b.onclick=()=>startLesson(i);$('#lesson-list').append(b);}if(!tutorial)return;const l=LESSONS[tutorial.index];$('#lesson-number').textContent=`Lesson ${tutorial.index+1} / ${LESSONS.length}`;$('#lesson-title').textContent=l.title;$('#lesson-text').textContent=l.text;$('#lesson-task').textContent=tutorial.done?'Lesson complete. You played the rule correctly.':notice||l.steps[tutorial.step].hint;$('#lesson-next').hidden=!tutorial.done;$('#lesson-next').textContent=tutorial.index===LESSONS.length-1?'Finish learning →':'Next lesson →';$('#lesson-hint').disabled=tutorial.done;let action=$('#lesson-action');if(!action){action=document.createElement('button');action.id='lesson-action';action.className='primary full';$('#lesson-task').after(action);}const want=tutorial.done?null:l.steps[tutorial.step].want;action.hidden=!want||!['harvest','pass','finish'].includes(want.kind);if(!action.hidden){action.textContent=want.kind==='harvest'?'Harvest +3 flux':'Finish turn';action.onclick=()=>commit(actions(s).find(a=>matches(a,want)));}}
