$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;selected=null;slot=Math.min(1,s.gates[s.turn].length);notice='';render();});$$('[data-slot]').forEach(b=>b.onclick=()=>{slot=+b.dataset.slot;render();});for(const t of ['game','learn','pieces'])$('#tab-'+t).onclick=()=>t==='game'?exitLesson():setTab(t);$('#nav-learn').onclick=()=>{document.body.classList.remove('focus-view');$('#focus').setAttribute('aria-pressed',false);$('#focus').textContent='Focus board';setTab('learn');};$('#nav-play').onclick=exitLesson;$('#start-welcome').onclick=()=>startLesson(0);$('#dismiss-welcome').onclick=()=>{$('#welcome').hidden=true;try{localStorage.setItem('chess-v2-intro','dismissed');}catch{}};
