function observation(){return {version:VERSION,revision,state:structuredClone(s),legalActions:actions(s),learning:!!tutorial};}
function submitAction(id,rev){if(tutorial)throw new Error('Exit learning mode first.');if(rev!==revision)throw new Error('Stale position. Read a new observation.');if(busy||auto)throw new Error('Pause the built-in bot first.');const a=actions(s).find(a=>a.id===id);if(!a)throw new Error('Illegal action ID.');commit(a);return observation();}
window.ChessV2=Object.freeze({getObservation:observation,submitAction});window.Faultline=window.ChessV2;$('#api-open').onclick=()=>$('#api').showModal();$('#export-observation').onclick=()=>download(observation(),'chess-v2-observation.json');$('#submit-bot-action').onclick=()=>{try{submitAction($('#bot-action').value.trim(),revision);$('#api-notice').textContent='Action accepted.';}catch(err){$('#api-notice').textContent=err.message;}};
$('#benchmark').onclick=()=>{if(benchWorker){benchWorker.terminate();benchWorker=null;$('#benchmark').textContent='Test 3 games';$('#bench-results').textContent='Test cancelled. Your match is unchanged.';return;}$('#benchmark').textContent='Stop tests';$('#bench-results').textContent='Running 3 isolated games, up to 120 turns each…';benchWorker=new Worker(new URL('./bot-worker.js',import.meta.url),{type:'module'});benchWorker.onmessage=e=>{const d=e.data;if(d.error){$('#bench-results').textContent='Test error: '+d.error;benchWorker.terminate();benchWorker=null;$('#benchmark').textContent='Test 3 games';}else if(d.done){benchWorker.terminate();benchWorker=null;$('#benchmark').textContent='Test 3 games';$('#bench-results').replaceChildren();for(const r of d.results){const p=document.createElement('p');p.textContent=`Game ${r.game}: ${r.winner==='limit'?'unfinished at turn cap':r.winner==='draw'?'draw':side(r.winner)+' wins'} · ${r.plies} turns.`;$('#bench-results').append(p);}const p=document.createElement('p');p.textContent=`${(d.ms/1000).toFixed(1)} seconds. Every action validated. Turn caps are not draws.`;$('#bench-results').append(p);}else if(d.progress)$('#bench-results').textContent=`Completed ${d.progress}/${d.total} games…`;};benchWorker.onerror=()=>{benchWorker.terminate();benchWorker=null;$('#benchmark').textContent='Test 3 games';$('#bench-results').textContent='The test worker could not run.';};benchWorker.postMessage({id:1,type:'benchmark',options:{games:3,maxPlies:120}});};
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopBot();auto=false;render();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){selected=null;if(!tutorial)mode='move';notice='';render();}});render();scheduleBot();
